def check_divisor(k, N=4026, M=1000):
    if N % k != 0:
        return None, "k is not a divisor"

    # Calculate 2x using the provided equation: 2x = 4026/k - k + 1
    two_x = N // k - k + 1

    # Check if 2x is even (so x is an integer)
    if two_x % 2 != 0:
        return None, "2x is odd, x is not an integer"

    x = two_x // 2
    y = x + k - 1

    # Check constraints: 1 <= x <= y <= 1000
    if x >= 1 and y <= M and x <= y:
        return (x, k), "Valid"
    else:
        return (x, k), "Failed bounds"

divisors = [1, 2, 3, 6, 11, 22, 33, 66, 61, 122, 183, 671, 366, 1342, 2013, 4026]
valid_counts = 0
results = []

for k in divisors:
    result = check_divisor(k)
    if result:
        data, status = result
        results.append((data, status))
        if status == "Valid":
            valid_counts += 1

print("--- Results ---")
print(f"Total valid sequences found: {valid_counts}")
for (x, k), status in results:
    print(f"k={k}, x={x}, y={x+k-1}. Status: {status}")

